281	    private static boolean isBlank(String value) {
282	        return value == null || value.isBlank();
283	    }
284	
285	    /**
286	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
287	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
288	     * lower-cased so that last names are compared case-insensitively.
289	     */
290	    private static String normalizeHousehold(String value) {
291	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
292	    }
293	
294	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
295	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
296	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
297	
298	    /**
299	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
300	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
301	     * upper-cased, and common street-type abbreviations are expanded token-by-token
302	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
303	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
304	     * used for every address comparison (household-duplicate detection and the shared household id).
305	     */
306	    private static String normalizeAddress(String value) {
307	        if (value == null) {
308	            return "";
309	        }
310	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
311	        if (collapsed.isEmpty()) {
312	            return "";
313	        }
314	        String[] tokens = collapsed.split(" ");
315	        StringBuilder sb = new StringBuilder();
316	        for (int i = 0; i < tokens.length; i++) {
317	            if (i > 0) {
318	                sb.append(' ');
319	            }
320	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
321	        }
322	        return sb.toString();
323	    }
324	
325	    /**
326	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
327	     * deterministic function of the normalized last name and address, so every owner that
328	     * shares those values maps to the same identifier regardless of creation order.
329	     */
330	    private static String householdId(String normalizedLastName, String normalizedAddress) {
331	        String key = normalizedLastName + "\n" + normalizedAddress;
332	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
333	    }
334	
335	    /**
336	     * Builds the {@code customerCode} assigned to a new owner, formatted
337	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
338	     * owner's last name, and {@code NNNN} is a global 4-digit zero-padded sequence equal to
339	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
340	     */
341	    private String nextCustomerCode(String lastName) {
342	        String letters = lastName == null ? "" : lastName.replaceAll("[^\\p{L}]", "");
343	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
344	        long sequence = this.clinicService.findAllOwners().size() + 1L;
345	        return String.format("%s-%04d", last3, sequence);
346	    }
347	
348	    /**
349	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
350	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
351	     * national one, a single leading {@code '0'} is dropped, and the default country code
352	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
353	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
354	     */
355	    private static String toE164(String telephone) {
356	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
357	        String digits;
358	        if (cleaned.startsWith("+")) {
359	            digits = cleaned.substring(1);
360	        } else {
361	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
362	            digits = "61" + national;
363	        }
364	        if (!digits.matches("[0-9]{8,15}")) {
365	            throw new InvalidTelephoneException(
366	                "telephone must form a valid E.164 number with 8 to 15 digits");
367	        }
368	        return "+" + digits;
369	    }
370	
371	    /**
372	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
373	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
374	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
375	     * stored and returned in canonical form.
376	     */
377	    private static String normalizeEmail(String email) {
378	        if (isBlank(email)) {
379	            return null;
380	        }
381	        String trimmed = email.trim();
382	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
383	            throw new InvalidEmailException("email must be a syntactically valid address");
384	        }
385	        return trimmed.toLowerCase(Locale.ROOT);
386	    }
387	}
