    return (int) this.clinicService.findAllOwners().stream()
        .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
            && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
        .count();
}

